-- ════════════════════════════════════════════════════════════════════════════
-- Masarak — Seed vocational_programs + vocational_institutes
-- 29 June 2026.  Single source of truth for /vocational (was hardcoded in
-- src/app/vocational/data.ts). Mirrors trackToDB()/instituteToDB() in
-- src/lib/entities.ts so the admin content inventory + DB-backed pages match.
--
-- Generated from data.ts (do not hand-edit — re-run gen_vocational_seed.mjs).
-- Idempotent: re-running upserts by primary key. Safe to apply more than once.
-- ════════════════════════════════════════════════════════════════════════════

-- ========== 18 VOCATIONAL PROGRAMS ==========
on conflict (id) do update set
  code = excluded.code, name = excluded.name, duration = excluded.duration, level = excluded.level, sector = excluded.sector, description = excluded.description, subjects = excluded.subjects, salary_lb = excluded.salary_lb, salary_gulf = excluded.salary_gulf, demand = excluded.demand, uni_equiv = excluded.uni_equiv, emoji = excluded.emoji, is_active = excluded.is_active, updated_at = now();

-- ========== 10 VOCATIONAL INSTITUTES ==========
on conflict (id) do update set
  name = excluded.name, region = excluded.region, type = excluded.type, specialties = excluded.specialties, emoji = excluded.emoji, is_active = excluded.is_active, updated_at = now();

-- Keep the BIGSERIAL sequence ahead of the explicit ids we just inserted, so
-- future admin-created institutes don't collide with 1..10.
select setval(
  pg_get_serial_sequence('vocational_institutes', 'id'),
  (select coalesce(max(id), 1) from vocational_institutes),
  true
);

-- ✅ Done. Expect 18 active programs + 10 active institutes.
